name:`edge:${m.from}->${m.to}:${k + 1}`,line:'STRAIGHT',m0:'POINT',m1:'POINT',
label:from===start?m.label:'',dashed:style.dashed,endCap:style.cap,color:style.color,weight:style.weight,
